import pandas as pd
import streamlit as st

# Set page layout
st.set_page_config(
    page_title="Remote Job Intelligence Dashboard",
    page_icon="💼",
    layout="wide",
)

st.title("💼 Remote Job Intelligence Dashboard")
st.markdown(
    "Explore real-time remote tech, data, and operations opportunities aggregated across multiple global APIs."
)


@st.cache_data
def load_data():
    """Loads the cleaned job dataset generated by job_fetcher.py."""
    try:
        df = pd.read_csv("cleaned_remote_jobs.csv")
        return df
    except FileNotFoundError:
        return pd.DataFrame()


df = load_data()

if df.empty:
    st.error(
        "No data file found! Make sure to run `uv run job_fetcher.py` first to generate 'cleaned_remote_jobs.csv'."
    )
else:
    # --- SIDEBAR FILTERS ---
    st.sidebar.header("🔍 Filter Options")

    # Keyword Search
    search_query = st.sidebar.text_input(
        "Search by Title or Company", ""
    ).strip()

    # Source Filter
    sources = ["All"] + sorted(df["Source"].dropna().unique().tolist())
    selected_source = st.sidebar.selectbox("API Source", sources)

    # Tech Skill Filter
    all_skills = set()
    for skills in df["Skills Extracted"].dropna():
        if skills != "General Analytics / Unspecified":
            for s in skills.split(", "):
                all_skills.add(s)

    selected_skills = st.sidebar.multiselect(
        "Filter by Required Tech Skill", sorted(list(all_skills))
    )

    # --- FILTER DATA ---
    filtered_df = df.copy()

    if search_query:
        mask = filtered_df["Title"].str.contains(
            search_query, case=False, na=False
        ) | filtered_df["Company"].str.contains(
            search_query, case=False, na=False
        )
        filtered_df = filtered_df[mask]

    if selected_source != "All":
        filtered_df = filtered_df[filtered_df["Source"] == selected_source]

    if selected_skills:
        for skill in selected_skills:
            filtered_df = filtered_df[
                filtered_df["Skills Extracted"].str.contains(
                    skill, case=False, na=False
                )
            ]

    # --- KEY METRICS CARDS ---
    col1, col2, col3 = st.columns(3)
    col1.metric("Total Jobs Found", len(filtered_df))
    col2.metric(
        "Unique Companies",
        filtered_df["Company"].nunique() if not filtered_df.empty else 0,
    )

    # Top skill calculation
    if not filtered_df.empty and selected_skills:
        top_skill = ", ".join(selected_skills)
    else:
        top_skill = "Python / SQL"
    col3.metric("Top In-Demand Skills", top_skill)

    st.markdown("---")

    # --- DATA TABLE & LINKS ---
    st.subheader("📋 Active Remote Job Openings")

    if filtered_df.empty:
        st.warning("No jobs match your current filter criteria.")
    else:
        for _, row in filtered_df.iterrows():
            with st.container():
                c1, c2 = st.columns([3, 1])
                with c1:
                    st.markdown(f"### [{row['Title']}]({row['Apply Link']})")
                    st.markdown(
                        f"**Company:** {row['Company']} | **Location:** {row['Location']} | **Source:** `{row['Source']}`"
                    )
                    st.markdown(
                        f"**Tech Stack:** `{row['Skills Extracted']}`"
                    )
                with c2:
                    st.markdown("<br>", unsafe_allow_html=True)
                    st.link_button("👉 Apply Now", row["Apply Link"])
                st.markdown("---")